//! End-to-end: build every fixture with the `brrrty` binary and compare it
//! to the reference output generated by real Eleventy.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use brrrty_compat::{AllowList, Outcome, compare_dirs};

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures")
}

/// Whether Node is here to run the fixture's JavaScript data, with its npm
/// packages installed (`npm ci --ignore-scripts`, into the git-ignored
/// `node_modules`) when it has a lock file.
fn node_ready(fixture: &Path) -> bool {
    let ci = std::env::var_os("CI").is_some();
    if Command::new("node").arg("--version").output().is_err() {
        assert!(!ci, "CI needs Node for {}", fixture.display());
        eprintln!("skipped {}: no node on PATH", fixture.display());
        return false;
    }
    let site = fixture.join("site");
    if site.join("package-lock.json").is_file() && !site.join("node_modules").is_dir() {
        let out = Command::new("npm")
            .args(["ci", "--ignore-scripts", "--no-audit", "--no-fund"])
            .current_dir(&site)
            .output();
        match out {
            Ok(o) if o.status.success() => {}
            other => {
                assert!(!ci, "npm ci failed in {}: {other:?}", site.display());
                eprintln!("skipped {}: npm ci failed: {other:?}", fixture.display());
                return false;
            }
        }
    }
    true
}

#[test]
fn every_fixture_matches_reference_output() {
    let mut names: Vec<PathBuf> = fs::read_dir(fixtures_dir())
        .expect("fixtures dir")
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.join("fixture.toml").is_file())
        .collect();
    names.sort();
    assert!(!names.is_empty(), "no fixtures found");

    for fixture in names {
        let text = fs::read_to_string(fixture.join("fixture.toml")).expect("fixture.toml");
        let cfg: toml::Table = text.parse().expect("valid fixture.toml");
        // JavaScript data runs in Node: CI has one; elsewhere a fixture
        // that needs it is skipped, saying so.
        if cfg.get("node").and_then(|v| v.as_bool()) == Some(true) && !node_ready(&fixture) {
            continue;
        }
        // Without `input`, the folders come from the fixture's config file.
        let input = cfg
            .get("input")
            .map(|v| v.as_str().expect("input is a string"));
        let epoch = cfg
            .get("source_date_epoch")
            .map(|v| v.as_integer().expect("source_date_epoch is whole seconds"));
        let passthrough: Vec<&str> = cfg
            .get("passthrough")
            .and_then(|v| v.as_array())
            .map(|a| a.iter().filter_map(|v| v.as_str()).collect())
            .unwrap_or_default();

        let out = tempfile::tempdir().expect("tempdir");
        let mut cmd = Command::new(env!("CARGO_BIN_EXE_brrrty"));
        cmd.current_dir(fixture.join("site"))
            .env_remove("SOURCE_DATE_EPOCH")
            .args(["build", "--output"])
            .arg(out.path());
        if let Some(input) = input {
            cmd.args(["--input", input]);
        }
        if let Some(epoch) = epoch {
            cmd.env("SOURCE_DATE_EPOCH", epoch.to_string());
        }
        // Dates printed in the local zone need the zone the reference was
        // built in.
        if let Some(tz) = cfg.get("tz") {
            cmd.env("TZ", tz.as_str().expect("tz is a zone name"));
        }
        // And the locale, for toLocaleString() and localeCompare() with no
        // locale.
        if let Some(lang) = cfg.get("lang") {
            cmd.env("LC_ALL", lang.as_str().expect("lang is a locale"));
        }
        for p in &passthrough {
            cmd.args(["--passthrough", p]);
        }
        // Pages Brrrty refuses, each with the output 11ty writes for it.
        let refused: Vec<(String, PathBuf)> = cfg
            .get("refused")
            .and_then(|v| v.as_table())
            .map(|t| {
                t.iter()
                    .map(|(page, out)| {
                        let out = out.as_str().expect("refused output is a path");
                        (page.clone(), PathBuf::from(out))
                    })
                    .collect()
            })
            .unwrap_or_default();
        let result = cmd.output().expect("run brrrty");
        let stderr = String::from_utf8_lossy(&result.stderr);
        if refused.is_empty() {
            assert!(
                result.status.success(),
                "brrrty failed on {}: {}\n{stderr}",
                fixture.display(),
                result.status,
            );
        } else {
            assert_eq!(
                result.status.code(),
                Some(1),
                "brrrty should refuse pages of {}:\n{stderr}",
                fixture.display()
            );
            // A page refused through a data file it uses is named by that
            // file's one problem, under `[refused_by]`.
            let by = cfg.get("refused_by").and_then(|v| v.as_table());
            for (page, _) in &refused {
                let named = match by.and_then(|t| t.get(page)).and_then(|v| v.as_str()) {
                    Some(file) => stderr.contains(&format!("× {file}:")),
                    None => {
                        stderr.contains(&format!("[{page}:"))
                            || stderr.contains(&format!("× {page}:"))
                    }
                };
                assert!(
                    named,
                    "{}: no problem for {page}:\n{stderr}",
                    fixture.display()
                );
            }
        }

        let report = compare_dirs(&fixture.join("expected"), out.path(), &AllowList::empty())
            .expect("compare");
        let failing: Vec<_> = report
            .results
            .iter()
            .filter(|r| match r.outcome {
                Outcome::Identical | Outcome::Equivalent => false,
                Outcome::Missing => !refused.iter().any(|(_, o)| *o == r.path),
                _ => true,
            })
            .collect();
        assert!(
            failing.is_empty(),
            "fixture {} differs:\n{}",
            fixture.display(),
            report.to_markdown(80)
        );
        for (page, output) in &refused {
            assert!(
                !out.path().join(output).exists(),
                "{}: {page} is refused but {} was written",
                fixture.display(),
                output.display()
            );
        }
    }
}

/// Without the pages that load `regex` and `css-extras`, Brrrty writes
/// highlight-mutation's js and css pages, and not the way 11ty writes them
/// with those pages: that is why it refuses them.
#[test]
fn a_page_that_changes_a_grammar_changes_other_pages() {
    let fixture = fixtures_dir().join("highlight-mutation");
    let site = tempfile::tempdir().expect("tempdir");
    fs::create_dir(site.path().join("src")).expect("src");
    fs::copy(
        fixture.join("site/brrrty.config.rhai"),
        site.path().join("brrrty.config.rhai"),
    )
    .expect("config");
    for page in ["b.md", "c.md", "e.md"] {
        fs::copy(
            fixture.join("site/src").join(page),
            site.path().join("src").join(page),
        )
        .expect("page");
    }
    let out = tempfile::tempdir().expect("tempdir");
    let result = Command::new(env!("CARGO_BIN_EXE_brrrty"))
        .current_dir(site.path())
        .args(["build", "--output"])
        .arg(out.path())
        .output()
        .expect("run brrrty");
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    let read = |dir: &Path, page: &str| {
        fs::read_to_string(dir.join(page).join("index.html")).expect("output")
    };
    let expected = fixture.join("expected");
    assert_eq!(read(out.path(), "c"), read(&expected, "c"));
    for page in ["b", "e"] {
        assert_ne!(read(out.path(), page), read(&expected, page), "{page}");
    }
}
